// homestorm's tables. The model is explained in docs/data-model.md.
//
// House conventions (from homework): uuid primary keys generated by Postgres, snake_case columns
// (`casing: "snake_case"` in drizzle.config.ts and db/index.ts), status values as plain text checked by Zod and a
// CHECK constraint, timestamps with time zone.

import type { MessageError, Usage } from "@homestorm/shared";
import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  customType,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";

const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

// ── Logins (ADR 0011): Better Auth's core tables, as in the sibling apps ──────

export const users = pgTable("users", {
  id: uuid().primaryKey().defaultRandom(),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: boolean().notNull().default(false),
  image: text(),
  createdAt: createdAt(),
  updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
});

export const sessions = pgTable("sessions", {
  id: uuid().primaryKey().defaultRandom(),
  userId: uuid()
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  token: text().notNull().unique(),
  expiresAt: timestamp({ withTimezone: true }).notNull(),
  ipAddress: text(),
  userAgent: text(),
  createdAt: createdAt(),
  updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
});

export const accounts = pgTable("accounts", {
  id: uuid().primaryKey().defaultRandom(),
  userId: uuid()
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  accountId: text().notNull(),
  providerId: text().notNull(),
  accessToken: text(),
  refreshToken: text(),
  accessTokenExpiresAt: timestamp({ withTimezone: true }),
  refreshTokenExpiresAt: timestamp({ withTimezone: true }),
  scope: text(),
  idToken: text(),
  // The password HASH lives here, not on `users`.
  password: text(),
  createdAt: createdAt(),
  updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
});

export const verifications = pgTable("verifications", {
  id: uuid().primaryKey().defaultRandom(),
  identifier: text().notNull(),
  value: text().notNull(),
  expiresAt: timestamp({ withTimezone: true }).notNull(),
  createdAt: createdAt(),
  updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
});

// ── Meetings ─────────────────────────────────────────────────────────────────

export const meetings = pgTable(
  "meetings",
  {
    id: uuid().primaryKey().defaultRandom(),
    title: text().notNull(),
    // Room rule: how long answers should be (ADR 0012). Blind or in turn is chosen per message, in the message box.
    answerLength: text().notNull().default("concise"),
    // Logical clock: +1 each time a message enters the shared record. A seat's turn sees messages whose
    // visible_seq <= the clock when the turn started (the visibility rule, ADR 0005).
    clock: integer().notNull().default(0),
    createdAt: createdAt(),
    updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [check("meetings_answer_length_valid", sql`${t.answerLength} IN ('concise', 'detailed')`)],
);

export const seats = pgTable(
  "seats",
  {
    id: uuid().primaryKey().defaultRandom(),
    meetingId: uuid()
      .notNull()
      .references(() => meetings.id, { onDelete: "cascade" }),
    // The exact model ID as llmgw lists it, and its owned_by (ADR 0002).
    model: text().notNull(),
    ownedBy: text().notNull(),
    displayName: text().notNull(),
    persona: text(),
    position: integer().notNull(),
    muted: boolean().notNull().default(false),
    reasoningEffort: text().notNull().default("low"),
    // This seat's own answer length; null follows the meeting's room rule (ADR 0012).
    answerLength: text(),
    // How much of the meeting its view may hold: small / standard / large / full; null is standard (ADR 0012).
    contextBudget: text(),
    // Removed seats stay, so their earlier messages keep a name in every view.
    removedAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    index("seats_meeting_idx").on(t.meetingId, t.position),
    check("seats_owned_by_valid", sql`${t.ownedBy} IN ('anthropic', 'openai-codex', 'deepseek')`),
    check("seats_reasoning_effort_valid", sql`${t.reasoningEffort} IN ('low', 'medium', 'high')`),
    check("seats_answer_length_valid", sql`${t.answerLength} IN ('concise', 'detailed')`),
    check(
      "seats_context_budget_valid",
      sql`${t.contextBudget} IN ('small', 'standard', 'large', 'full')`,
    ),
  ],
);

export const rounds = pgTable(
  "rounds",
  {
    id: uuid().primaryKey().defaultRandom(),
    meetingId: uuid()
      .notNull()
      .references(() => meetings.id, { onDelete: "cascade" }),
    number: integer().notNull(),
    mode: text().notNull(),
    // The seats called, in answering order.
    seatIds: jsonb().$type<string[]>().notNull(),
    // The chair message that started it, if any. No FK: messages already point at rounds.
    promptMessageId: uuid(),
    replyToId: uuid(),
    wrapKind: text(),
    status: text().notNull().default("running"),
    createdAt: createdAt(),
    finishedAt: timestamp({ withTimezone: true }),
  },
  (t) => [
    index("rounds_meeting_idx").on(t.meetingId, t.number),
    check("rounds_mode_valid", sql`${t.mode} IN ('blind', 'in_turn', 'single', 'wrap_up')`),
    check("rounds_status_valid", sql`${t.status} IN ('running', 'done', 'stopped')`),
  ],
);

export const messages = pgTable(
  "messages",
  {
    id: uuid().primaryKey().defaultRandom(),
    meetingId: uuid()
      .notNull()
      .references(() => meetings.id, { onDelete: "cascade" }),
    // Creation order, for showing the transcript.
    seq: integer().generatedAlwaysAsIdentity(),
    authorKind: text().notNull(),
    seatId: uuid().references(() => seats.id, { onDelete: "cascade" }),
    roundId: uuid().references(() => rounds.id, { onDelete: "cascade" }),
    replyToId: uuid(),
    content: text().notNull().default(""),
    status: text().notNull(),
    error: jsonb().$type<MessageError>(),
    // Chair messages: where it went.
    sendMode: text(),
    targetSeatIds: jsonb().$type<string[]>(),
    wrapKind: text(),
    hiddenFromSeats: boolean().notNull().default(false),
    // The meeting clock when it entered the shared record; null until then.
    visibleSeq: integer(),
    // Seat messages: the meeting clock when the turn started.
    cutoffSeq: integer(),
    // Tracing (ADR 0009): what was called, and what llmgw reported.
    model: text(),
    ownedBy: text(),
    reasoningEffort: text(),
    usage: jsonb().$type<Usage>(),
    costUsd: doublePrecision(),
    llmgwReqId: text(),
    requestId: text(),
    trimmedCount: integer().notNull().default(0),
    // The view's size by the budget estimate when the turn started.
    viewTokens: integer(),
    stoppedEarly: boolean().notNull().default(false),
    createdAt: createdAt(),
    startedAt: timestamp({ withTimezone: true }),
    finishedAt: timestamp({ withTimezone: true }),
  },
  (t) => [
    index("messages_meeting_seq_idx").on(t.meetingId, t.seq),
    index("messages_round_idx").on(t.roundId),
    check(
      "messages_author_kind_valid",
      sql`${t.authorKind} IN ('chair', 'seat', 'event', 'brief')`,
    ),
    check(
      "messages_status_valid",
      sql`${t.status} IN ('queued', 'streaming', 'done', 'stopped', 'error', 'skipped')`,
    ),
    check("messages_seat_has_seat", sql`${t.authorKind} <> 'seat' OR ${t.seatId} IS NOT NULL`),
  ],
);

/** Raw bytes (Postgres `bytea`), as a Node Buffer. */
const bytea = customType<{ data: Buffer; driverData: Buffer }>({ dataType: () => "bytea" });

/**
 * Images and text files on a chair message or a brief version (ADR 0016). Never changed once saved: a new brief
 * version copies the rows it keeps, so every version stays whole.
 */
export const attachments = pgTable(
  "attachments",
  {
    id: uuid().primaryKey().defaultRandom(),
    meetingId: uuid()
      .notNull()
      .references(() => meetings.id, { onDelete: "cascade" }),
    messageId: uuid()
      .notNull()
      .references(() => messages.id, { onDelete: "cascade" }),
    position: integer().notNull(),
    kind: text().notNull(),
    name: text().notNull(),
    mime: text().notNull(),
    sizeBytes: integer().notNull(),
    width: integer(),
    height: integer(),
    textChars: integer(),
    // Image bytes, or a text file as UTF-8.
    data: bytea().notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index("attachments_message_idx").on(t.messageId, t.position),
    index("attachments_meeting_idx").on(t.meetingId),
    check("attachments_kind_valid", sql`${t.kind} IN ('image', 'text')`),
  ],
);
